packaging.pylock._url_name:
def _url_name(url: str | None) -> str | None:
    if not url:
        return None
    url_path = urlparse(url).path
    return url_path.rsplit('/', 1)[-1]

packaging.direct_url._strip_auth_from_ne:
def _strip_auth_from_netloc(netloc: str, safe_user_passwords: Collection[str]) -> str:
    if '@' not in netloc:
        return netloc
    (user_pass, netloc_no_user_pass) = netloc.split('@', 1)
    if user_pass in safe_user_passwords:
        return netloc
    if _PEP610_USER_PASS_ENV_VARS_REGEX.match(user_pass):
        return netloc
    return netloc_no_user_pass

packaging.dependency_groups._normalize_g:
def _normalize_group_names(dependency_groups: Mapping[(str, Sequence[str | Mapping[(str, str)]])], errors: _ErrorCollector) -> dict[(str, Sequence[str | Mapping[(str, str)]])]:
    original_names: dict[(str, list[str])] = {}
    normalized_groups: dict[(str, Sequence[str | Mapping[(str, str)]])] = {}
    for (group_name, value) in dependency_groups.items():
        normed_group_name = _normalize_name(group_name)
        original_names.setdefault(normed_group_name, []).append(group_name)
        normalized_groups[normed_group_name] = value
    for (normed_name, names) in original_names.items():
        if len(names) > 1:
            errors.error(DuplicateGroupNames(f"Duplicate dependency group names: {normed_name} ({', '.join(names)})"))
    return normalized_groups

packaging.pylock._get_required_as:
def _get_required_as(d: Mapping[(str, Any)], expected_type: type[_T], target_type: Callable[([_T], _T2)], key: str) -> _T2:
    """Get a required value from the dict, verify it's the expected type,
